from __future__ import annotations

"""Index transforms for position-based playlist operations.

Two responsibilities live here:

* **Raw application** — given a tuple of tracks and an op with concrete
  indices, produce the new tuple. This assumes the indices are already correct
  for the current list.
* **Rebasing** — given a late op and the ordered list of ops that were applied
  after the late op's base snapshot, shift the late op's indices so they point
  at the tracks the author meant. An insert before our position pushes us right;
  a remove before our position pulls us left; a move does both at once.

The raw-application functions never rebase. Callers that hand them indices
written against an older snapshot must rebase first.
"""

from playlist_models import AppliedOp, PlaylistTrack, PositionalOp


def apply_op_to_tracks(
    tracks: tuple[PlaylistTrack, ...],
    op: PositionalOp,
    effective_index: int,
    effective_to_index: int = -1,
) -> tuple[PlaylistTrack, ...]:
    """Apply ``op`` to ``tracks`` using already-resolved indices."""

    items = list(tracks)
    if op.kind == "insert":
        bounded = _bounded_insert_index(effective_index, len(items))
        items.insert(bounded, PlaylistTrack(track_id=str(op.track_id), added_by=op.actor_id))
        return tuple(items)

    if op.kind == "remove":
        if effective_index < 0 or effective_index >= len(items):
            raise IndexError(f"remove index {effective_index} out of range")
        del items[effective_index]
        return tuple(items)

    if op.kind == "move":
        if effective_index < 0 or effective_index >= len(items):
            raise IndexError(f"move from_index {effective_index} out of range")
        track = items.pop(effective_index)
        target = effective_to_index
        if target < 0:
            raise IndexError("move to_index out of range")
        if target > len(items):
            target = len(items)
        items.insert(target, track)
        return tuple(items)

    raise ValueError(f"unsupported op kind: {op.kind}")


def _bounded_insert_index(index: int, length: int) -> int:
    if index < 0:
        return 0
    if index > length:
        return length
    return index


def _shift_for_prior(position: int, prior: AppliedOp) -> int:
    """Shift a single position by one already-applied op.

    Inserts at or before ``position`` push it right by one. Removes strictly
    before ``position`` pull it left by one. A move is a remove from its source
    followed by an insert at its destination.
    """

    shifted = position
    if prior.kind == "insert":
        if prior.effective_index <= position:
            shifted += 1
    elif prior.kind == "remove":
        if prior.effective_index < position:
            shifted -= 1
    elif prior.kind == "move":
        source = prior.effective_index
        dest = prior.effective_to_index
        if source < position:
            shifted -= 1
        if dest <= shifted:
            shifted += 1
    return shifted


def _shift_insert_position(position: int, prior: AppliedOp) -> int:
    """Shift an insert anchor by a prior op.

    Inserts use a slightly different rule at the boundary: a prior insert at
    exactly our anchor still pushes us right so two concurrent inserts at the
    same spot keep both authors' tracks in landing order.
    """

    shifted = position
    if prior.kind == "insert":
        if prior.effective_index <= position:
            shifted += 1
    elif prior.kind == "remove":
        if prior.effective_index < position:
            shifted -= 1
    elif prior.kind == "move":
        source = prior.effective_index
        dest = prior.effective_to_index
        if source < position:
            shifted -= 1
        if dest <= shifted:
            shifted += 1
    return shifted


def rebase_index(position: int, prior_ops: list[AppliedOp], is_insert: bool) -> int:
    """Fold ``position`` through every prior op in order."""

    current = position
    for prior in prior_ops:
        if is_insert:
            current = _shift_insert_position(current, prior)
        else:
            current = _shift_for_prior(current, prior)
        if current < 0:
            current = 0
    return current


def rebase_op_over(op: PositionalOp, prior_ops: list[AppliedOp]) -> tuple[int, int]:
    """Return the effective ``(index, to_index)`` for ``op`` after rebasing.

    ``to_index`` is ``-1`` for non-move ops.
    """

    if not prior_ops:
        if op.kind == "move":
            return op.from_index, op.to_index
        return op.index, -1

    if op.kind == "insert":
        return rebase_index(op.index, prior_ops, is_insert=True), -1

    if op.kind == "remove":
        return rebase_index(op.index, prior_ops, is_insert=False), -1

    if op.kind == "move":
        new_from = rebase_index(op.from_index, prior_ops, is_insert=False)
        new_to = rebase_index(op.to_index, prior_ops, is_insert=True)
        return new_from, new_to

    raise ValueError(f"unsupported op kind: {op.kind}")


def raw_indices(op: PositionalOp) -> tuple[int, int]:
    """The op's indices with no rebasing applied."""

    if op.kind == "move":
        return op.from_index, op.to_index
    return op.index, -1

