from __future__ import annotations

"""Append-only log of operations that were applied to a playlist.

Each applied op is recorded with the version it produced. To rebase a late op,
the engine needs the set of ops applied *since* that op's base version, in the
order they landed. That ordered slice is the transform the late op's indices
must pass through.
"""

from playlist_models import AppliedOp, PositionalOp


class OpLog:
    def __init__(self) -> None:
        self._entries: list[AppliedOp] = []
        self._seen_op_ids: set[str] = set()

    def record(
        self,
        op: PositionalOp,
        base_version: int,
        result_version: int,
        effective_index: int,
        effective_to_index: int = -1,
    ) -> AppliedOp:
        applied = AppliedOp(
            op_id=op.op_id,
            kind=op.kind,
            actor_id=op.actor_id,
            base_version=base_version,
            result_version=result_version,
            effective_index=effective_index,
            effective_to_index=effective_to_index,
            track_id=op.track_id,
        )
        self._entries.append(applied)
        self._seen_op_ids.add(op.op_id)
        return applied

    def has_op(self, op_id: str) -> bool:
        return op_id in self._seen_op_ids

    def entries(self) -> list[AppliedOp]:
        return list(self._entries)

    def ops_since(self, base_version: int) -> list[AppliedOp]:
        """Ops whose result_version is strictly greater than ``base_version``.

        These are the concurrent edits a later op must be rebased over. They are
        returned in the order they were applied.
        """

        return [entry for entry in self._entries if entry.result_version > base_version]

    def ops_between(self, low_version: int, high_version: int) -> list[AppliedOp]:
        return [
            entry
            for entry in self._entries
            if low_version < entry.result_version <= high_version
        ]

    def last_version(self) -> int:
        if not self._entries:
            return 0
        return self._entries[-1].result_version

    def count(self) -> int:
        return len(self._entries)

    def actor_op_count(self, actor_id: str) -> int:
        return sum(1 for entry in self._entries if entry.actor_id == actor_id)

    def op_ids(self) -> list[str]:
        return [entry.op_id for entry in self._entries]

