from __future__ import annotations

"""Validation for incoming positional ops against a playlist length.

These checks run on the *effective* indices, after any rebasing, because that
is the list the op actually touches. An insert may target one past the end; a
remove or a move source must point at a real track.
"""

from playlist_models import PositionalOp


def insert_index_ok(index: int, length: int) -> bool:
    return 0 <= index <= length


def remove_index_ok(index: int, length: int) -> bool:
    return 0 <= index < length


def move_indices_ok(from_index: int, to_index: int, length: int) -> bool:
    if length == 0:
        return False
    if not (0 <= from_index < length):
        return False
    # After removing the source, the list is one shorter, so the destination
    # may sit at the new end.
    return 0 <= to_index <= length - 1


def validate_effective(
    op: PositionalOp,
    effective_index: int,
    effective_to_index: int,
    length: int,
) -> str | None:
    """Return a rejection reason for out-of-range effective indices, else None."""

    if op.kind == "insert":
        if not insert_index_ok(effective_index, length):
            return "insert_index_out_of_range"
        return None

    if op.kind == "remove":
        if not remove_index_ok(effective_index, length):
            return "remove_index_out_of_range"
        return None

    if op.kind == "move":
        if not move_indices_ok(effective_index, effective_to_index, length):
            return "move_index_out_of_range"
        return None

    return "unsupported_op_kind"


def validate_raw_shape(op: PositionalOp) -> str | None:
    """Cheap structural checks that do not depend on the playlist length."""

    if op.kind == "insert" and (op.track_id is None or not str(op.track_id).strip()):
        return "insert_missing_track"
    if op.kind == "move" and op.from_index == op.to_index:
        return "move_noop"
    return None


def describe_validation(reason: str | None) -> str:
    if reason is None:
        return "ok"
    return reason.replace("_", " ")

