"""Domain models for collaborative playlist editing.

A collaborative playlist is an ordered list of tracks. Several listeners can
edit the same playlist at once from different devices. Each device composes its
edits against the *snapshot* it last saw, so every operation carries the
``base_snapshot_id`` it was written against. When two people edit at the same
time, the second op to land was written against an older view of the list, and
its raw indices no longer point at the tracks the author meant.

Operations are position based:

* ``insert`` puts ``track_id`` at ``index`` (shifting later tracks right).
* ``remove`` deletes whatever sits at ``index``.
* ``move`` takes the track at ``from_index`` and reinserts it at ``to_index``.

The models here are plain value objects. The transform and application logic
lives in the rebase and engine layers.
"""

from dataclasses import dataclass, field, replace


VALID_OP_KINDS = ("insert", "remove", "move")


def _require_text(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} is required")


def _require_index(value: int, field_name: str) -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{field_name} must be an int")
    if value < 0:
        raise ValueError(f"{field_name} must be non-negative")


@dataclass(frozen=True)
class PlaylistTrack:
    """A single entry in a collaborative playlist."""

    track_id: str
    added_by: str = "system"

    def __post_init__(self) -> None:
        _require_text(self.track_id, "track_id")
        _require_text(self.added_by, "added_by")


@dataclass(frozen=True)
class PositionalOp:
    """A position-based edit composed against ``base_snapshot_id``.

    ``index`` is used by ``insert`` and ``remove``. ``from_index`` and
    ``to_index`` are used by ``move``. ``track_id`` is only meaningful for
    ``insert``.
    """

    op_id: str
    kind: str
    actor_id: str
    base_snapshot_id: str
    index: int = 0
    from_index: int = 0
    to_index: int = 0
    track_id: str | None = None

    def __post_init__(self) -> None:
        _require_text(self.op_id, "op_id")
        _require_text(self.actor_id, "actor_id")
        _require_text(self.base_snapshot_id, "base_snapshot_id")
        if self.kind not in VALID_OP_KINDS:
            raise ValueError(f"unsupported op kind: {self.kind}")
        if self.kind in ("insert", "remove"):
            _require_index(self.index, "index")
        if self.kind == "insert":
            if self.track_id is None or not str(self.track_id).strip():
                raise ValueError("insert requires track_id")
        if self.kind == "move":
            _require_index(self.from_index, "from_index")
            _require_index(self.to_index, "to_index")

    def with_index(self, index: int) -> "PositionalOp":
        return replace(self, index=index)

    def with_move(self, from_index: int, to_index: int) -> "PositionalOp":
        return replace(self, from_index=from_index, to_index=to_index)

    def primary_index(self) -> int:
        """The index a reviewer would call this op's main target."""

        if self.kind == "move":
            return self.from_index
        return self.index


@dataclass(frozen=True)
class PlaylistSnapshot:
    """An immutable view of a playlist at a given version.

    ``snapshot_id`` is the public token a client echoes back on its next op.
    ``version`` is the monotonic integer the server uses to order applied ops.
    """

    playlist_id: str
    snapshot_id: str
    version: int
    tracks: tuple[PlaylistTrack, ...] = ()

    def __post_init__(self) -> None:
        _require_text(self.playlist_id, "playlist_id")
        _require_text(self.snapshot_id, "snapshot_id")
        if not isinstance(self.version, int) or isinstance(self.version, bool):
            raise ValueError("version must be an int")
        if self.version < 0:
            raise ValueError("version must be non-negative")

    def track_ids(self) -> list[str]:
        return [track.track_id for track in self.tracks]

    def length(self) -> int:
        return len(self.tracks)

    def with_tracks(
        self,
        tracks: tuple[PlaylistTrack, ...],
        snapshot_id: str,
        version: int,
    ) -> "PlaylistSnapshot":
        return PlaylistSnapshot(
            playlist_id=self.playlist_id,
            snapshot_id=snapshot_id,
            version=version,
            tracks=tracks,
        )


@dataclass(frozen=True)
class AppliedOp:
    """A record of one op that was applied, with the version it produced."""

    op_id: str
    kind: str
    actor_id: str
    base_version: int
    result_version: int
    effective_index: int
    effective_to_index: int = -1
    track_id: str | None = None


@dataclass
class RebaseResult:
    """Outcome of folding one op against the live playlist.

    ``status`` is ``applied``, ``rebased``, ``noop`` (idempotent replay) or
    ``rejected``. ``rebased`` means the indices were transformed because the op
    was written against an older snapshot.
    """

    status: str
    op_id: str
    snapshot: PlaylistSnapshot
    reason: str = ""
    applied: AppliedOp | None = None
    rebase_distance: int = 0
    fields: dict = field(default_factory=dict)

    def is_change(self) -> bool:
        return self.status in ("applied", "rebased")


def build_snapshot(
    playlist_id: str,
    snapshot_id: str,
    version: int,
    track_ids: list[str],
    added_by: str = "seed",
) -> PlaylistSnapshot:
    tracks = tuple(PlaylistTrack(track_id=tid, added_by=added_by) for tid in track_ids)
    return PlaylistSnapshot(
        playlist_id=playlist_id,
        snapshot_id=snapshot_id,
        version=version,
        tracks=tracks,
    )


def build_insert(op_id: str, actor: str, base: str, index: int, track_id: str) -> PositionalOp:
    return PositionalOp(
        op_id=op_id,
        kind="insert",
        actor_id=actor,
        base_snapshot_id=base,
        index=index,
        track_id=track_id,
    )


def build_remove(op_id: str, actor: str, base: str, index: int) -> PositionalOp:
    return PositionalOp(
        op_id=op_id,
        kind="remove",
        actor_id=actor,
        base_snapshot_id=base,
        index=index,
    )


def build_move(op_id: str, actor: str, base: str, from_index: int, to_index: int) -> PositionalOp:
    return PositionalOp(
        op_id=op_id,
        kind="move",
        actor_id=actor,
        base_snapshot_id=base,
        from_index=from_index,
        to_index=to_index,
    )

