class PlaylistStore:
    def __init__(self) -> None:
        self._head: dict[str, PlaylistSnapshot] = {}
        self._history: dict[str, list[PlaylistSnapshot]] = {}

    def seed(self, snapshot: PlaylistSnapshot) -> None:
        self._head[snapshot.playlist_id] = snapshot
        self._history.setdefault(snapshot.playlist_id, []).append(snapshot)

    def head(self, playlist_id: str) -> PlaylistSnapshot | None:
        return self._head.get(playlist_id)

    def require_head(self, playlist_id: str) -> PlaylistSnapshot:
        snapshot = self._head.get(playlist_id)
        if snapshot is None:
            raise KeyError(f"unknown playlist: {playlist_id}")
        return snapshot

    def commit(self, snapshot: PlaylistSnapshot) -> PlaylistSnapshot:
        self._head[snapshot.playlist_id] = snapshot
        self._history.setdefault(snapshot.playlist_id, []).append(snapshot)
        return snapshot

    def history(self, playlist_id: str) -> list[PlaylistSnapshot]:
        return list(self._history.get(playlist_id, []))

    def version(self, playlist_id: str) -> int:
        snapshot = self._head.get(playlist_id)
        if snapshot is None:
            return -1
        return snapshot.version

    def known_playlists(self) -> list[str]:
        return list(self._head)

    def contains(self, playlist_id: str) -> bool:
        return playlist_id in self._head

    def length(self, playlist_id: str) -> int:
        snapshot = self._head.get(playlist_id)
        if snapshot is None:
            return 0
        return snapshot.length()

    def snapshot_count(self, playlist_id: str) -> int:
        return len(self._history.get(playlist_id, []))

    def snapshot_at_version(self, playlist_id: str, version: int) -> PlaylistSnapshot | None:
        for snapshot in self._history.get(playlist_id, []):
            if snapshot.version == version:
                return snapshot
        return None

    def latest_snapshot_id(self, playlist_id: str) -> str | None:
        snapshot = self._head.get(playlist_id)
        if snapshot is None:
            return None
        return snapshot.snapshot_id

    def track_ids(self, playlist_id: str) -> list[str]:
        snapshot = self._head.get(playlist_id)
        if snapshot is None:
            return []
        return snapshot.track_ids()

    def stats(self, playlist_id: str) -> dict[str, object]:
        snapshot = self._head.get(playlist_id)
        return {
            "playlist_id": playlist_id,
            "exists": snapshot is not None,
            "version": -1 if snapshot is None else snapshot.version,
            "length": 0 if snapshot is None else snapshot.length(),
            "snapshot_count": self.snapshot_count(playlist_id),
        }

