from __future__ import annotations

"""Tracks the version each issued snapshot_id corresponds to.

Every time the playlist changes, a new ``snapshot_id`` is minted and bound to a
monotonic ``version``. Clients echo the ``base_snapshot_id`` they composed an op
against. The engine asks this registry two things:

* What version was that base snapshot? (so it can count ops applied since.)
* Is that base the current head?

A base that is not the current head means concurrent edits landed in between,
and the op's indices were written against an older list.
"""

from playlist_models import PlaylistSnapshot


class SnapshotRegistry:
    def __init__(self) -> None:
        self._version_by_snapshot: dict[str, int] = {}
        self._snapshot_by_version: dict[int, str] = {}
        self._head_snapshot: str | None = None
        self._head_version: int = -1

    def register(self, snapshot: PlaylistSnapshot) -> None:
        """Record a freshly minted snapshot and advance the head."""

        self._version_by_snapshot[snapshot.snapshot_id] = snapshot.version
        self._snapshot_by_version[snapshot.version] = snapshot.snapshot_id
        if snapshot.version >= self._head_version:
            self._head_version = snapshot.version
            self._head_snapshot = snapshot.snapshot_id

    def knows(self, snapshot_id: str) -> bool:
        return snapshot_id in self._version_by_snapshot

    def version_of(self, snapshot_id: str) -> int | None:
        return self._version_by_snapshot.get(snapshot_id)

    def head_snapshot(self) -> str | None:
        return self._head_snapshot

    def head_version(self) -> int:
        return self._head_version

    def is_head(self, snapshot_id: str) -> bool:
        """Whether ``snapshot_id`` is the current head of the playlist."""

        return snapshot_id == self._head_snapshot

    def is_current(self, snapshot_id: str) -> bool:
        """Whether an op based on ``snapshot_id`` needs no rebasing.

        An op needs no rebasing only when its base snapshot already matches the
        head version exactly.
        """

        base_version = self.version_of(snapshot_id)
        if base_version is None:
            return False
        return base_version == self._head_version

    def distance_to_head(self, snapshot_id: str) -> int | None:
        """How many versions have passed since ``snapshot_id`` was head.

        Returns ``None`` for an unknown snapshot. Zero means the base is the
        head; a positive number means that many newer versions exist.
        """

        base_version = self.version_of(snapshot_id)
        if base_version is None:
            return None
        gap = self._head_version - base_version
        if gap < 0:
            return 0
        return gap

    def known_snapshot_ids(self) -> list[str]:
        return list(self._version_by_snapshot)

    def snapshot_for_version(self, version: int) -> str | None:
        return self._snapshot_by_version.get(version)

